const commandResult = $input.first().json;
if (Number(commandResult.exitCode ?? 0) !== 0) {
  throw new Error('RFQ parser exited unsuccessfully: ' + String(commandResult.stderr ?? ''));
}
const raw = String(commandResult.stdout ?? '').trim();
const match = /^DEMO ONLY \| rows=(\d+) priced=(\d+) review=(\d+) priced_subtotal=(\d+\.\d{2}) \| (outputs\/quote_n8n_demo\.xlsx)$/.exec(raw);
if (!match) {
  throw new Error('RFQ parser output did not match the approved local demo contract');
}
const rows = Number(match[1]);
const priced = Number(match[2]);
const review = Number(match[3]);
if (rows < 1 || priced < 0 || review < 0 || priced + review !== rows) {
  throw new Error('RFQ parser returned inconsistent line counts');
}
return [{json: {status: 'DRAFT / DO NOT SEND', rows, priced, review, approvedLinesSubtotalUSD: match[4], outputRelativePath: match[5], requiresHumanReview: review > 0}}];
